import React from 'react';
import styled from 'styled-components';
import Square from '../Square';
import ChessPiece from '../ChessPiece';
import { useWebSocket } from '../../hooks/useWebSocket';

const BoardContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  width: 640px;
  height: 640px;
  border: 2px solid #333;
`;

interface ChessBoardProps {
  onMove: (from: string, to: string) => void;
  board: any;
}

const ChessBoard: React.FC<ChessBoardProps> = ({ onMove, board }) => {
  const [selectedSquare, setSelectedSquare] = React.useState<string | null>(null);

  const handleSquareClick = (square: string) => {
    if (!selectedSquare) {
      // First click - select the piece
      if (board[square]?.piece) {
        setSelectedSquare(square);
      }
    } else {
      // Second click - attempt to move
      onMove(selectedSquare, square);
      setSelectedSquare(null);
    }
  };

  const renderSquare = (square: string, i: number) => {
    const file = String.fromCharCode(97 + (i % 8)); // a-h
    const rank = 8 - Math.floor(i / 8); // 1-8
    const squareId = `${file}${rank}`;
    const piece = board[squareId]?.piece;
    const isSelected = selectedSquare === squareId;
    const isLight = (Math.floor(i / 8) + (i % 8)) % 2 === 0;

    return (
      <Square
        key={squareId}
        isLight={isLight}
        isSelected={isSelected}
        onClick={() => handleSquareClick(squareId)}
      >
        {piece && (
          <ChessPiece
            type={piece.type}
            color={piece.color}
          />
        )}
      </Square>
    );
  };

  return (
    <BoardContainer>
      {Array(64).fill(null).map((_, i) => renderSquare('', i))}
    </BoardContainer>
  );
};

export default ChessBoard;
